import shutil
import subprocess
from pathlib import Path
STAGING_ROOT = Path('/srv/listings/staging')
PUBLISHED_ROOT = Path('/srv/listings/published')
OPTIMIZER_SCRIPT = Path('/opt/listing-tools/optimize_photos.py')
ALLOWED_PHOTO_EXTENSIONS = {'.jpg', '.jpeg', '.png', '.webp'}

def process_and_publish_listing_photos(listing_id: str, max_width_pixels: int=2048) -> dict:
    staging_directory_for_listing = STAGING_ROOT / listing_id
    optimized_output_directory = staging_directory_for_listing / 'optimized'
    published_directory_for_listing = PUBLISHED_ROOT / listing_id / 'photos'
    if not staging_directory_for_listing.is_dir():
        return {'listing_id': listing_id, 'error': 'No staged photos found for this listing'}
    optimizer_command_arguments = ['python', str(OPTIMIZER_SCRIPT), '--input', str(staging_directory_for_listing), '--output', str(optimized_output_directory), '--max-width', str(max_width_pixels)]
    optimizer_process_result = subprocess.run(optimizer_command_arguments, capture_output=True, text=True, timeout=600)
    if optimizer_process_result.returncode != 0:
        return {'listing_id': listing_id, 'error': 'Photo optimization failed', 'stderr': optimizer_process_result.stderr.strip()[-2000:]}
    published_directory_for_listing.mkdir(parents=True, exist_ok=True)
    # Replace the listing's photo set: remove previously published photos first
    removed_previous_photo_filenames = []
    for previously_published_photo_path in sorted(published_directory_for_listing.iterdir()):
        if previously_published_photo_path.is_file():
            previously_published_photo_path.unlink()
            removed_previous_photo_filenames.append(previously_published_photo_path.name)
    moved_photo_filenames = []
    for optimized_photo_path in sorted(optimized_output_directory.iterdir()):
        if optimized_photo_path.suffix.lower() not in ALLOWED_PHOTO_EXTENSIONS:
            continue
        destination_photo_path = published_directory_for_listing / optimized_photo_path.name
        shutil.move(str(optimized_photo_path), str(destination_photo_path))
        moved_photo_filenames.append(optimized_photo_path.name)
    return {'listing_id': listing_id, 'published_directory': str(published_directory_for_listing), 'published_photo_count': len(moved_photo_filenames), 'published_photos': moved_photo_filenames, 'removed_previous_photos': removed_previous_photo_filenames, 'optimizer_output': optimizer_process_result.stdout.strip()[-1000:]}
